session_start();require_once '../config/database.php';require_once 'lib.php';require_once 'assignment_service.php';if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}
$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);$railroadId=(int)$railroad['id'];$id=(int)($_GET['id']??$_POST['assignment_id']??0);$error='';
function ttLoadEditableAssignment(PDO$pdo,int$id,int$railroadId):array{$stmt=$pdo->prepare('SELECT a.*,s.session_number,s.status session_status FROM operation_assignments a JOIN operating_sessions s ON s.id=a.session_id AND s.railroad_id=a.railroad_id WHERE a.id=? AND a.railroad_id=?');$stmt->execute([$id,$railroadId]);$a=$stmt->fetch(PDO::FETCH_ASSOC);if(!$a){http_response_code(404);die('Assignment not found.');}return$a;}
$assignment=ttLoadEditableAssignment($pdo,$id,$railroadId);if($assignment['start_method']==='inherit'||!in_array($assignment['end_plan'],ttAssignmentEndPlans(),true)){http_response_code(409);die('This legacy assignment is read-only. Inheritance and legacy end plans are preserved for history but deferred to a future focused update.');}$listStatuses=ttAssignmentListStatuses($pdo,$id,$railroadId);if(!ttAssignmentIsEditable($assignment,$listStatuses)){http_response_code(409);die('This assignment can no longer be edited because its session, assignment, or retained switch-list history is frozen.');}
if($_SERVER['REQUEST_METHOD']==='POST')try{
 ttOperationsRequireCsrf();$pdo->beginTransaction();$stmt=$pdo->prepare('SELECT a.*,s.status session_status FROM operation_assignments a JOIN operating_sessions s ON s.id=a.session_id AND s.railroad_id=a.railroad_id WHERE a.id=? AND a.railroad_id=? FOR UPDATE');$stmt->execute([$id,$railroadId]);$locked=$stmt->fetch(PDO::FETCH_ASSOC);if(!$locked||!ttAssignmentIsEditable($locked,ttAssignmentListStatuses($pdo,$id,$railroadId)))throw new RuntimeException('This assignment crossed the safe editing boundary and was not changed.');$data=ttAssignmentNormalizeInput($pdo,$railroadId,(int)$locked['session_id'],$_POST,$id);$job=$data['job'];
 $stmt=$pdo->prepare('UPDATE operation_assignments SET job_template_id=?,title_snapshot=?,type_snapshot=?,description_snapshot=?,operating_pattern=?,status=?,operating_base_industry_id=?,starting_track=?,start_method=?,prepared_cut_id=?,requested_car_count=?,prepared_cut_car_count=?,difficulty=?,crew_name=?,predecessor_assignment_id=?,dependency_mode=?,end_plan=?,end_industry_id=?,end_track=?,notes=? WHERE id=? AND railroad_id=?');$status='draft';$stmt->execute([$data['job_id'],$job['job_name'],$job['job_type'],$job['description'],$data['pattern'],$status,$data['base_id'],$data['starting_track'],$data['start_method'],$data['cut_id'],$data['requested'],$data['prepared_cut_count'],$data['difficulty'],$data['crew'],$data['predecessor'],$data['dependency'],$data['end_plan'],$data['end_id'],$data['end_track'],$data['notes'],$id,$railroadId]);$reserved=ttReservedEquipmentIds($pdo,$railroadId,$id);ttAssignmentReplaceLocomotives($pdo,$id,$railroadId,$data['locomotive_ids'],$reserved);ttAssignmentReplaceStartingCars($pdo,$id,$railroadId,$data,$reserved,$locked['prepared_cut_id']?(int)$locked['prepared_cut_id']:null);ttCancelDraftSwitchLists($pdo,$id,$railroadId,'Invalidated because the assignment settings were edited.');$pdo->commit();header('Location: session_edit.php?id='.(int)$locked['session_id']);exit;
}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();$assignment=ttLoadEditableAssignment($pdo,$id,$railroadId);}
$stmt=$pdo->prepare('SELECT id,job_name,job_type FROM jobs WHERE railroad_id=? AND active=1 ORDER BY job_name');$stmt->execute([$railroadId]);$jobs=$stmt->fetchAll(PDO::FETCH_ASSOC);$stmt=$pdo->prepare('SELECT id,industry_name FROM industries WHERE railroad_id=? AND active=1 ORDER BY industry_name');$stmt->execute([$railroadId]);$industries=$stmt->fetchAll(PDO::FETCH_ASSOC);$stmt=$pdo->prepare("SELECT id,reporting_marks,road_number,road_name FROM equipment WHERE railroad_id=? AND active=1 AND equipment_class='Locomotive' ORDER BY reporting_marks,road_number");$stmt->execute([$railroadId]);$locomotives=$stmt->fetchAll(PDO::FETCH_ASSOC);$stmt=$pdo->prepare("SELECT e.id,e.reporting_marks,e.road_number,e.equipment_type,e.current_industry_id,e.current_track,i.industry_name FROM equipment e JOIN industries i ON i.id=e.current_industry_id AND i.railroad_id=e.railroad_id WHERE e.railroad_id=? AND e.active=1 AND COALESCE(e.equipment_class,'')<>'Locomotive' AND NOT EXISTS(SELECT 1 FROM operation_assignment_starting_cars ac JOIN operation_assignments a ON a.id=ac.assignment_id WHERE ac.equipment_id=e.id AND a.railroad_id=e.railroad_id AND a.id<>? AND a.status IN('draft','ready','waiting','in_progress','needs_review')) ORDER BY e.reporting_marks,e.road_number");$stmt->execute([$railroadId,$id]);$cars=$stmt->fetchAll(PDO::FETCH_ASSOC);$stmt=$pdo->prepare("SELECT c.*,COUNT(pc.equipment_id) car_count,i.industry_name FROM prepared_cuts c JOIN industries i ON i.id=c.current_industry_id AND i.railroad_id=c.railroad_id LEFT JOIN prepared_cut_cars pc ON pc.prepared_cut_id=c.id WHERE c.railroad_id=? AND (c.id=? OR (c.status='ready' AND NOT EXISTS(SELECT 1 FROM prepared_cut_cars pc2 JOIN operation_assignment_starting_cars ac2 ON ac2.equipment_id=pc2.equipment_id JOIN operation_assignments a2 ON a2.id=ac2.assignment_id WHERE pc2.prepared_cut_id=c.id AND a2.railroad_id=c.railroad_id AND a2.id<>? AND a2.status IN('draft','ready','waiting','in_progress','needs_review')))) GROUP BY c.id ORDER BY c.cut_number");$stmt->execute([$railroadId,(int)$assignment['prepared_cut_id'],$id]);$cuts=$stmt->fetchAll(PDO::FETCH_ASSOC);$stmt=$pdo->prepare('SELECT id,assignment_number,title_snapshot FROM operation_assignments WHERE session_id=? AND railroad_id=? AND id<>? ORDER BY sequence_number');$stmt->execute([(int)$assignment['session_id'],$railroadId,$id]);$predecessors=$stmt->fetchAll(PDO::FETCH_ASSOC);$stmt=$pdo->prepare('SELECT equipment_id FROM operation_assignment_locomotives WHERE assignment_id=? ORDER BY position');$stmt->execute([$id]);$selectedLocos=array_map('intval',$stmt->fetchAll(PDO::FETCH_COLUMN));$stmt=$pdo->prepare('SELECT equipment_id FROM operation_assignment_starting_cars WHERE assignment_id=? ORDER BY position');$stmt->execute([$id]);$selectedCars=array_map('intval',$stmt->fetchAll(PDO::FETCH_COLUMN));$patterns=ttJobTypes();$patternOverride=ttAssignmentPatternOverrideValue($assignment);$advanced=$assignment['operating_pattern']!==$assignment['type_snapshot']||(int)$assignment['requested_car_count']!==10||(int)$assignment['prepared_cut_car_count']!==10||$assignment['difficulty']!=='medium'||$assignment['predecessor_assignment_id']||$assignment['end_plan']!=='return_origin'||trim((string)$assignment['notes'])!=='';
?>
