s="col-md-3 tt-field-end"><label class="form-label">End Location <span class="text-muted">(required for Terminate elsewhere)</span></label><select class="form-select" name="end_industry_id"><option value="">As planned</option><?php foreach($industries as$i):?><option value="<?=(int)$i['id']?>" <?=(int)$assignment['end_industry_id']===(int)$i['id']?'selected':''?>><?=ttHtml($i['industry_name'])?></option><?php endforeach;?></select></div><div class="col-md-3 tt-field-end"><label class="form-label">End Track</label><input class="form-control" name="end_track" value="<?=ttHtml($assignment['end_track'])?>" maxlength="120"></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="2"><?=ttHtml($assignment['notes'])?></textarea></div></div></details></div><div><button class="btn btn-primary">Save Assignment</button> <a class="btn btn-secondary" href="session_edit.php?id=<?=(int)$assignment['session_id']?>">Back to Session</a></div></form></section></div><script src="../assets/js/assignment-form.js"></script><?php include '../includes/footer.php';?>
